"""Sound for Brain Snack v3, all generated by our own code (no samples, no recordings).

- Collision notes: every bounce/break/clone plays the next note of a public-domain melody
  (composers who died more than 95 years ago; we write our own note sequences).
- Game sound effects: fail thud, success chord, cymbal swell, sweep, clack, tick, ding, gong.
- Simple beds: soft pad and a light drum loop.
"""
from __future__ import annotations

import math

import numpy as np

SR = 48000

# Public-domain melodies (MIDI note numbers), our own transcriptions of the tunes.
MELODIES: dict[str, list[int]] = {
    # Grieg, In the Hall of the Mountain King (1875)
    "mountain_king": [59, 61, 62, 64, 66, 62, 66, 65, 61, 65, 64, 60, 64,
                      59, 61, 62, 64, 66, 62, 66, 71, 69, 66, 62, 66, 69],
    # Beethoven, Ode to Joy (1824)
    "ode_to_joy": [64, 64, 65, 67, 67, 65, 64, 62, 60, 60, 62, 64, 64, 62, 62,
                   64, 64, 65, 67, 67, 65, 64, 62, 60, 60, 62, 64, 62, 60, 60],
    # Beethoven, Fur Elise (1810)
    "fur_elise": [76, 75, 76, 75, 76, 71, 74, 72, 69, 60, 64, 69, 71, 64, 68, 71, 72,
                  64, 76, 75, 76, 75, 76, 71, 74, 72, 69, 60, 64, 69, 71, 64, 72, 71, 69],
    # Traditional, Twinkle Twinkle (melody 1761)
    "twinkle": [60, 60, 67, 67, 69, 69, 67, 65, 65, 64, 64, 62, 62, 60,
                67, 67, 65, 65, 64, 64, 62, 67, 67, 65, 65, 64, 64, 62],
    # Mozart, Rondo alla Turca (1783)
    "turkish_march": [71, 69, 68, 69, 72, 74, 72, 71, 72, 76, 77, 76, 75, 76,
                      83, 81, 80, 81, 83, 81, 80, 81, 84],
    # Grieg, Morning Mood (1875)
    "morning_mood": [68, 64, 63, 61, 63, 64, 68, 64, 63, 61, 63, 64, 63, 64, 68, 64, 68, 69, 64, 69, 68, 64, 63, 61],
    # Bizet, Habanera (1875) - the falling chromatic line
    "habanera": [74, 73, 72, 72, 71, 70, 69, 69, 68, 67, 66, 65, 64, 65, 66, 64],
    # Rimsky-Korsakov, Flight of the Bumblebee (1900) - chromatic swirl
    "bumblebee": [76, 75, 74, 73, 72, 77, 76, 75, 76, 75, 74, 73, 72, 73, 74, 75,
                  76, 75, 74, 73, 72, 77, 76, 75, 76, 75, 74, 73, 72, 73, 74, 75],
}

PENTATONIC = [0, 2, 4, 7, 9]


def midi_hz(m: float) -> float:
    return 440.0 * 2 ** ((m - 69) / 12)


def pentatonic(low: int = 72, high: int = 96) -> list[int]:
    return [n for n in range(low, high + 1) if (n - 60) % 12 in PENTATONIC]


# ---------- instruments ----------

INSTRUMENTS = {
    # (frequency ratio, amplitude, decay per second)
    "marimba": [(1.0, 1.0, 6.0), (3.93, 0.35, 16.0), (9.2, 0.10, 30.0)],
    "celesta": [(1.0, 1.0, 3.0), (2.0, 0.30, 5.0), (3.0, 0.12, 7.0), (4.1, 0.05, 9.0)],
    "glass": [(1.0, 1.0, 1.8), (2.76, 0.22, 3.6), (5.40, 0.07, 6.0)],
    "bell": [(1.0, 1.0, 1.3), (2.0, 0.45, 1.8), (2.4, 0.28, 2.4), (3.0, 0.22, 2.8), (4.5, 0.15, 3.4)],
    "kalimba": [(1.0, 1.0, 4.0), (5.4, 0.18, 12.0), (8.9, 0.06, 18.0)],
}


def tone(freq: float, dur: float = 0.9, kind: str = "marimba", vel: float = 0.8) -> np.ndarray:
    n = int(dur * SR)
    t = np.arange(n, dtype=np.float32) / SR
    if kind == "pluck":                            # Karplus-Strong plucked string
        period = max(2, int(SR / freq))
        rng = np.random.default_rng(int(freq))
        buf = rng.uniform(-1, 1, period).astype(np.float32)
        out = np.empty(n, np.float32)
        for i in range(n):
            out[i] = buf[i % period]
            buf[i % period] = 0.996 * 0.5 * (buf[i % period] + buf[(i + 1) % period])
        sig = out
    else:
        sig = np.zeros(n, np.float32)
        for ratio, amp, decay in INSTRUMENTS.get(kind, INSTRUMENTS["marimba"]):
            f = freq * ratio
            if f < SR / 2:
                sig += amp * np.sin(2 * np.pi * f * t) * np.exp(-decay * t)
    attack = min(n, int(0.003 * SR))
    sig[:attack] *= np.linspace(0, 1, attack, dtype=np.float32)
    fade = min(n, int(0.02 * SR))
    sig[-fade:] *= np.linspace(1, 0, fade, dtype=np.float32)
    return sig * (0.25 + 0.75 * vel) / max(1.0, len(INSTRUMENTS.get(kind, [1])) * 0.6)


def render_notes(events: list[tuple[float, int, float]], total_s: float, kind: str = "marimba",
                 min_gap: float = 0.09, dur: float = 0.9, transpose: int = 0) -> np.ndarray:
    """events: (time s, midi note, velocity 0..1). Notes closer than min_gap are merged (rattles)."""
    out = np.zeros(int(total_s * SR) + SR, np.float32)
    cache: dict[tuple[int, int], np.ndarray] = {}
    last_t = -1.0
    for t, note, vel in sorted(events):
        if t - last_t < min_gap or t < 0:
            continue
        last_t = t
        key = (int(note) + transpose, int(vel * 8))
        if key not in cache:
            cache[key] = tone(midi_hz(key[0]), dur, kind, key[1] / 8)
        s = int(t * SR)
        clip = cache[key][: max(0, len(out) - s)]
        out[s:s + len(clip)] += clip
    return out[: int(total_s * SR)]


# ---------- effects ----------

def _env(n: int, attack: float, decay: float) -> np.ndarray:
    t = np.arange(n, dtype=np.float32) / SR
    e = np.exp(-decay * t)
    a = min(n, int(attack * SR))
    if a:
        e[:a] *= np.linspace(0, 1, a, dtype=np.float32)
    return e


def _noise(n: int, seed: int = 0) -> np.ndarray:
    return np.random.default_rng(seed).uniform(-1, 1, n).astype(np.float32)


def thud(dur: float = 0.45) -> np.ndarray:
    n = int(dur * SR)
    t = np.arange(n, dtype=np.float32) / SR
    f = 110 * np.exp(-6 * t) + 45
    body = np.sin(2 * np.pi * np.cumsum(f) / SR) * _env(n, 0.002, 9)
    return (body + 0.25 * _noise(n) * _env(n, 0.001, 40)) * 0.9


def chord(notes: list[int], dur: float = 1.6, kind: str = "bell", vel: float = 0.8) -> np.ndarray:
    parts = [tone(midi_hz(n), dur, kind, vel) for n in notes]
    return np.sum(parts, axis=0) / max(1.0, len(parts) ** 0.5)


def fail_figure() -> np.ndarray:
    seq = [67, 63, 58]
    out = np.zeros(int(0.9 * SR), np.float32)
    for i, n in enumerate(seq):
        s = int(i * 0.16 * SR)
        clip = tone(midi_hz(n), 0.5, "glass", 0.7)
        out[s:s + len(clip)] += clip[: len(out) - s]
    return out


def cymbal_swell(dur: float = 1.4) -> np.ndarray:
    n = int(dur * SR)
    noise = _noise(n, 7)
    hp = noise - np.concatenate([[0], noise[:-1]])          # crude high-pass = bright
    env = np.linspace(0, 1, n, dtype=np.float32) ** 2
    return hp * env * 0.35


def success() -> np.ndarray:
    a = chord([60, 64, 67, 72], 2.2, "bell", 0.9)
    s = cymbal_swell(1.0)
    out = np.zeros(max(len(a), len(s) + int(0.1 * SR)), np.float32)
    out[: len(s)] += s
    out[int(0.95 * SR): int(0.95 * SR) + len(a)] += a[: len(out) - int(0.95 * SR)]
    return out


def sweep_up(dur: float = 0.8) -> np.ndarray:
    n = int(dur * SR)
    t = np.arange(n, dtype=np.float32) / SR
    f = 200 * (12 ** (t / dur))
    return np.sin(2 * np.pi * np.cumsum(f) / SR).astype(np.float32) * np.linspace(0.1, 0.6, n) * _env(n, 0.01, 0.5)


def clack(pitch: float = 1.0, seed: int = 0) -> np.ndarray:
    n = int(0.09 * SR)
    t = np.arange(n, dtype=np.float32) / SR
    body = np.sin(2 * np.pi * 1800 * pitch * t) * _env(n, 0.0005, 70)
    return (0.6 * body + 0.5 * _noise(n, seed) * _env(n, 0.0005, 120)) * 0.8


def tick() -> np.ndarray:
    n = int(0.03 * SR)
    t = np.arange(n, dtype=np.float32) / SR
    return np.sin(2 * np.pi * 2600 * t) * _env(n, 0.0005, 160) * 0.7


def ding(base: float = 1046) -> np.ndarray:
    return tone(base, 1.0, "bell", 0.9)


def gong(dur: float = 2.5) -> np.ndarray:
    n = int(dur * SR)
    t = np.arange(n, dtype=np.float32) / SR
    sig = np.zeros(n, np.float32)
    for ratio, amp, dec in ((1.0, 1.0, 0.9), (1.48, 0.6, 1.2), (2.03, 0.45, 1.6), (2.69, 0.3, 2.2), (3.47, 0.2, 3.0)):
        sig += amp * np.sin(2 * np.pi * 98 * ratio * t) * np.exp(-dec * t)
    return sig * _env(n, 0.004, 0.0) * 0.5


def whoosh(dur: float = 0.5, seed: int = 3) -> np.ndarray:
    n = int(dur * SR)
    noise = _noise(n, seed)
    out = np.zeros(n, np.float32)
    acc = 0.0
    for i in range(0, n, 64):                               # moving low-pass = "air"
        k = 0.02 + 0.3 * math.sin(math.pi * i / n)
        seg = noise[i:i + 64]
        for j in range(len(seg)):
            acc += k * (seg[j] - acc)
            out[i + j] = acc
    return out * np.sin(np.linspace(0, np.pi, n, dtype=np.float32)) * 1.6


def pad(seconds: float, root: int = 48, kind: str = "major", vol: float = 0.12) -> np.ndarray:
    n = int(seconds * SR)
    t = np.arange(n, dtype=np.float32) / SR
    steps = [0, 4, 7, 11] if kind == "major" else [0, 3, 7, 10]
    sig = np.zeros(n, np.float32)
    for i, s in enumerate(steps):
        f = midi_hz(root + s)
        sig += np.sin(2 * np.pi * f * t + i) * (0.6 + 0.4 * np.sin(2 * np.pi * (0.07 + 0.03 * i) * t))
    fade = min(n, SR)
    sig[:fade] *= np.linspace(0, 1, fade)
    sig[-fade:] *= np.linspace(1, 0, fade)
    return sig / len(steps) * vol


def drum_loop(seconds: float, bpm: int = 128, vol: float = 0.25) -> np.ndarray:
    n = int(seconds * SR)
    out = np.zeros(n + SR, np.float32)
    beat = 60.0 / bpm
    kn = int(0.25 * SR)
    kt = np.arange(kn, dtype=np.float32) / SR
    kick = np.sin(2 * np.pi * np.cumsum(55 + 90 * np.exp(-30 * kt)) / SR) * np.exp(-12 * kt)
    hat = _noise(int(0.04 * SR), 11) * _env(int(0.04 * SR), 0.0005, 90) * 0.3
    t = 0.0
    i = 0
    while t < seconds:
        s = int(t * SR)
        if i % 2 == 0:
            out[s:s + kn] += kick
        out[s + int(beat / 2 * SR): s + int(beat / 2 * SR) + len(hat)] += hat
        t += beat
        i += 1
    return out[:n] * vol


def place(mix: np.ndarray, clip: np.ndarray, at_s: float, gain: float = 1.0) -> None:
    s = int(at_s * SR)
    if s >= len(mix) or s < 0:
        return
    e = min(len(mix), s + len(clip))
    mix[s:e] += clip[: e - s] * gain


def to_stereo(mono: np.ndarray, peak: float = 0.89) -> np.ndarray:
    m = np.max(np.abs(mono)) or 1.0
    mono = mono * min(1.0, peak / m)
    return np.stack([mono, mono], axis=1).astype(np.float32)
